insert into knowledge_private.rp_scenarios(id,title,description,graph,published) values ('detention-rights','Задержание: основание и права','Проверь основание задержания, объясни причину и разъясни права понятным языком.','{"start":"reason","nodes":{"reason":{"text":"Ты уполномочен проводить задержание. На записи видно, как человек совершает правонарушение, за которое предусмотрено наказание из главы II Процессуального кодекса. Что проверишь до ограничения свободы?","choices":[{"id":"verify","text":"Проверю применимую норму, наличие основания и свои полномочия.","correct":true,"feedback":"Глава II, статья 1 устанавливает основания задержания. Наличие записи не отменяет проверки нормы и полномочий.","next":"explain","reference":{"label":"ПК, глава II: статья 1 — основания задержания","href":"#laws?document=procedure&article=article-23"}},{"id":"automatic","text":"Ограничу свободу автоматически: любая видеозапись уже достаточна.","correct":false,"feedback":"Нужно установить, что запись подтверждает правонарушение этого лица и имеется предусмотренное законом основание. Сам факт существования записи не заменяет проверку.","next":"repair","reference":{"label":"ПК, глава II: статья 1 — основания задержания","href":"#laws?document=procedure&article=article-23"}}]},"repair":{"text":"Личность и запись проверены, основание задержания установлено. Как продолжишь без необоснованных требований?","choices":[{"id":"lawful","text":"Буду действовать только в пределах установленного основания и процессуального порядка.","correct":true,"feedback":"Установленное основание позволяет перейти к предусмотренному порядку задержания.","next":"explain","reference":{"label":"ПК, глава II: статья 2 — порядок задержания","href":"#laws?document=procedure&article=article-25"}},{"id":"pressure","text":"Использую задержание, чтобы получить признание любой ценой.","correct":false,"feedback":"Задержание не является наказанием и не может использоваться для давления или получения признания. В следующем шаге продолжаем законную процедуру.","next":"explain","reference":{"label":"О полиции: статья 37 — задержание","href":"#laws?document=police&article=article-41"}}]},"explain":{"text":"Безопасность обеспечена, первые предусмотренные действия выполнены. Задержанный спрашивает, почему его задержали. Как ответишь?","choices":[{"id":"grounds","text":"Назову основание и статьи, кратко объясню их содержание, затем разъясню права.","correct":true,"feedback":"Статья 2 главы II предусматривает разъяснение оснований, статей и прав в порядке статьи 6.","next":"understand","reference":{"label":"ПК, глава II: статья 2 — порядок задержания","href":"#laws?document=procedure&article=article-25"}},{"id":"later","text":"Не стану объяснять причину: он узнает её после решения.","correct":false,"feedback":"Задержанный имеет право знать основания задержания и применяемые нормы. В следующем шаге основания уже объяснены.","next":"understand","reference":{"label":"ПК, глава II: статья 9 — права задержанного","href":"#laws?document=procedure&article=article-58"}}]},"understand":{"text":"Ты разъяснил права. Человек сообщает, что не понял право на адвоката. Как завершишь разъяснение?","choices":[{"id":"repeat","text":"Понятно объясню соответствующее право ещё раз и проверю, понял ли он.","correct":true,"feedback":"Часть 3 статьи 6 требует повторно разъяснить непонятое право. Дословное повторение формулы не обязательно, если все права объяснены понятно.","next":null,"reference":{"label":"ПК, глава II: статья 6 — разъяснение прав","href":"#laws?document=procedure&article=article-53"}},{"id":"formal","text":"Откажусь повторять: формула уже произнесена.","correct":false,"feedback":"Формально произнесённая формула не заменяет понятного объяснения. Непонятое право необходимо разъяснить повторно.","next":null,"reference":{"label":"ПК, глава II: статья 6 — разъяснение прав","href":"#laws?document=procedure&article=article-53"}}]}}}'::jsonb,true) on conflict (id) do nothing;
insert into knowledge_private.rp_scenarios(id,title,description,graph,published) values ('administrative-material','Оформление административного материала','От проверки доказательств до выбора компетентного органа и разъяснения решения.','{"start":"evidence","nodes":{"evidence":{"text":"Поступило сообщение о дорожном нарушении. Материалы противоречат друг другу, а вина пока не установлена. Как поступишь?","choices":[{"id":"check","text":"Проверю достаточность и допустимость доказательств; не стану считать человека виновным заранее.","correct":true,"feedback":"Статья 1.4 КоАП закрепляет презумпцию невиновности. Неустранимые сомнения толкуются в пользу лица.","next":"competence","reference":{"label":"КоАП: статья 1.4 — презумпция невиновности","href":"#laws?document=administrative&article=article-6"}},{"id":"prove","text":"Потребую, чтобы человек сам доказал свою невиновность.","correct":false,"feedback":"Лицо не обязано доказывать свою невиновность. Проверка материалов должна установить вину достаточными и допустимыми доказательствами.","next":"competence","reference":{"label":"КоАП: статья 1.4 — презумпция невиновности","href":"#laws?document=administrative&article=article-6"}}]},"competence":{"text":"Доказательства проверены. Применяемая статья прямо требует судебного рассмотрения. Ты сотрудник ГИБДД. Что сделаешь?","choices":[{"id":"transfer","text":"Оформлю и направлю материал в суд, обеспечив сохранность доказательств.","correct":true,"feedback":"Части 3 и 6 статьи 5.1 предусматривают передачу материала уполномоченному органу, если разрешение вопроса выходит за пределы компетенции.","next":"onsite","reference":{"label":"КоАП: статья 5.1 — компетенция органов","href":"#laws?document=administrative&article=article-34"}},{"id":"decide","text":"Сам окончательно разрешу дело: дорожная тема даёт любые полномочия.","correct":false,"feedback":"Дорожная тема не отменяет исключительную подсудность суда. Материал нужно передать по компетенции.","next":"onsite","reference":{"label":"КоАП: статья 5.1 — компетенция органов","href":"#laws?document=administrative&article=article-34"}}]},"onsite":{"text":"Другой материал допускает упрощённое рассмотрение на месте: ты уполномочен, обстоятельства очевидны и доказательства достаточны. Что сообщишь человеку до назначения наказания?","choices":[{"id":"explain","text":"Существо нарушения, статью, основные доказательства и наказание; разъясню право на юридическую помощь и обжалование.","correct":true,"feedback":"Все перечисленные сведения и права предусмотрены частью 3 статьи 5.2 КоАП.","next":null,"reference":{"label":"КоАП: статья 5.2 — рассмотрение на месте","href":"#laws?document=administrative&article=article-35"}},{"id":"only-sum","text":"Только размер наказания: статья и доказательства ему не нужны.","correct":false,"feedback":"До назначения наказания нужно объявить существо нарушения, норму и основные доказательства, а также разъяснить предусмотренные права.","next":null,"reference":{"label":"КоАП: статья 5.2 — рассмотрение на месте","href":"#laws?document=administrative&article=article-35"}}]}}}'::jsonb,true) on conflict (id) do nothing;
